@router.get("/sources/{sid}/file")
def source_file(sid: str):
    import config
    metadata = source_call("get", "source", sid)
    root = config.RAW_DATA_DIR.resolve()
    filename = metadata.get("filename")
    if not isinstance(filename, str) or not filename.strip():
